def circular_shift(x, shift):
    x_str = str(x)
    length = len(x_str)

    if shift == 0:
        return x_str
    elif shift >= length:
        return x_str[::-1]
    else:
        shift = shift % length
        return x_str[-shift:] + x_str[:-shift]

